def _install_guards():
    op.execute("""
    CREATE FUNCTION finance_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN RAISE EXCEPTION 'finance records are immutable; use compensating events' USING ERRCODE='23514'; END $$;
    """)
    for table in ("finance_records", "finance_evidence", "finance_entries", "finance_lines"):
        op.execute(
            f"CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON {table} FOR EACH ROW EXECUTE FUNCTION finance_immutable()"
        )
    op.execute("""
    CREATE FUNCTION finance_period_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
      PERFORM pg_advisory_xact_lock(404003);
      IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'period deletion forbidden' USING ERRCODE='23514'; END IF;
      IF TG_OP = 'UPDATE' THEN
        IF OLD.status <> 'open' OR NEW.status <> 'closed' OR NEW.closure_evidence IS NULL
          OR NEW.starts_on <> OLD.starts_on OR NEW.ends_on <> OLD.ends_on OR NEW.actor_id <> OLD.actor_id OR NEW.id <> OLD.id
        THEN RAISE EXCEPTION 'only evidenced period closure allowed' USING ERRCODE='23514'; END IF;
      END IF;
      IF EXISTS (SELECT 1 FROM finance_periods WHERE id <> NEW.id AND starts_on <= NEW.ends_on AND ends_on >= NEW.starts_on)
      THEN RAISE EXCEPTION 'overlapping period' USING ERRCODE='23514'; END IF;
      RETURN NEW;
    END $$;
    CREATE TRIGGER period_guard BEFORE INSERT OR UPDATE OR DELETE ON finance_periods FOR EACH ROW EXECUTE FUNCTION finance_period_guard();
    CREATE FUNCTION finance_entry_insert() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
      PERFORM pg_advisory_xact_lock(404003);
      IF NOT EXISTS (SELECT 1 FROM finance_periods WHERE id=NEW.period_id AND status='open' AND NEW.posting_date BETWEEN starts_on AND ends_on FOR UPDATE)
      THEN RAISE EXCEPTION 'closed or invalid period' USING ERRCODE='23514'; END IF;
      NEW.transaction_id := txid_current();
      RETURN NEW;
    END $$;
    CREATE TRIGGER entry_insert BEFORE INSERT ON finance_entries FOR EACH ROW EXECUTE FUNCTION finance_entry_insert();
    CREATE FUNCTION finance_line_insert() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
      IF NOT EXISTS (SELECT 1 FROM finance_entries WHERE id=NEW.entry_id AND transaction_id=txid_current())
      THEN RAISE EXCEPTION 'cannot append to a committed posting' USING ERRCODE='23514'; END IF;
      RETURN NEW;
    END $$;
    CREATE TRIGGER line_insert BEFORE INSERT ON finance_lines FOR EACH ROW EXECUTE FUNCTION finance_line_insert();
    CREATE FUNCTION finance_check_balance() RETURNS trigger LANGUAGE plpgsql AS $$
    DECLARE target uuid; debits numeric; credits numeric; count_lines integer;
    BEGIN
      IF TG_TABLE_NAME='finance_entries' THEN target:=NEW.id; ELSE target:=NEW.entry_id; END IF;
      SELECT coalesce(sum(debit_minor),0),coalesce(sum(credit_minor),0),count(*) INTO debits,credits,count_lines FROM finance_lines WHERE entry_id=target;
      IF count_lines<2 OR debits<=0 OR debits<>credits THEN RAISE EXCEPTION 'unbalanced financial posting' USING ERRCODE='23514'; END IF;
      RETURN NULL;
    END $$;
    CREATE CONSTRAINT TRIGGER balance_entry AFTER INSERT ON finance_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION finance_check_balance();
    CREATE CONSTRAINT TRIGGER balance_lines AFTER INSERT ON finance_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION finance_check_balance();
    """)
